// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address actor, uint256 deposited, uint256 withdrawn) public {
        vm.assume(deposited <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        deposited = bound(deposited, 1, type(uint128).max);
        withdrawn = bound(withdrawn, 0, deposited);

        vm.deal(actor, deposited);
        vm.prank(actor);
        c.deposit{value: deposited}();

        vm.prank(actor);
        c.withdraw(withdrawn);

        uint256 beforeRefund = actor.balance;

        // refund must send back exactly the remaining balance (deposited - withdrawn)
        vm.prank(actor);
        c.refund();

        assertTrue(
            actor.balance == beforeRefund + (deposited - withdrawn) && address(c).balance == 0,
            "refund must return deposited - withdrawn"
        );
    }
}
